        var pressedB = await pressDialogActionByLabel(runId, ['Bẩm Thầy Ông Nội'], 'trả việc hộ tống');
        if (!pressedB) pressedB = clickDialogChoice(['Bẩm Thầy Ông Nội'], 'Bẩm Thầy Ông Nội');
        if (!pressedB) { dumpDialogChoices(); closeDialogIfOpen(); await sleep(600); continue; }
