    for (i = 0; i < ws.length; i++) if (nowMs < ws[i].end) return ws[i];
    var base = vcVnMidnight(nowMs) + 24 * 3600 * 1000, g = CONBANG.gio[0];
    var s = base + g[0] * 3600000 + g[1] * 60000;
