      if (!alive(runId)) { vcRelease(); return { r: 'stopped' }; }
      var hRead = vcNutHeightPct(); // height% thanh lực game vẽ lúc thả — chỉ quan sát ghi nhật ký, không quyết thả (v3 thả theo giờ cố định)
      var phaLuc = vcPhase();
