      await sleep(600);
      if (chestDone()) { log('Hang Động: đã mở Linh Dược Rương (kiểm chứng cờ hang_dong_da_lay_ruong) — bước xong'); return 'done'; }
      var st = readQuestState();
      var still = null;
      for (var i = 0; i < st.objs.length; i++) if (st.objs[i].text === obj.text) { still = st.objs[i]; break; }
      if (!still || still.done) { log('Hang Động: bước "' + obj.text + '" đã xong sau khi mở rương'); return 'done'; }
      log('Hang Động: chạm rương mà chưa thấy mở (chìa trong túi: ' + keyCount() + ') — vòng sau thử lại');
