          log('Đại Hội: vào đài' + (round ? ' vòng ' + round : '') + (opp ? ' — đối thủ: ' + opp : '') + ' — bật Bay + Chạy + Auto + kỹ năng theo nhịp + di chuyển vòng liên tục quanh đối thủ giữ khoảng cách (đánh tới hết trận, không tự rút lui)');
          setStatus('Đại Hội: đang thi đấu' + (round ? ' vòng ' + round : '') + (opp ? ' — ' + opp : ''));
