          var kite = arenaKiteWatch(runId, function () { return inDaiHoiArena(readMapId()); }, 'Đại Hội'); // v1.71: cách đánh đài như Chiến Bảng (Bui bổ sung 20:41: áp dụng cho cả Đại Hội)
          var winsBefore = wins;
