      log('Tích Đạo Hạnh bằng đả tọa ở ' + altar.label + ' (trần 60/phút theo mã game)' + (startExp != null ? ' — Đạo Hạnh hiện ' + startExp : ''));
      // v1.52 (Bui lệnh 07:40 ngày 2026-11-27): đi tới đài đá dùng cách nhanh nhất game
