  function countYeuDanCap3Plus() {
    var total = 0, any = false;
    ['yeu_dan_cap_3', 'yeu_dan_cap_4', 'yeu_dan_cap_5', 'yeu_dan_cap_6'].forEach(function (id) {
      var n = countItem(id);
      if (n != null) { total += n; any = true; }
    });
    return any ? total : null;
  }
