        hxSizeSet(hxSizeSel.value);
        log('Huyết Xích: số người khi mời tổ đội = ' + (hxSizeSel.value === 'auto' ? 'theo cảnh giới (Luyện Khí 4 · Trúc Cơ Sơ Kỳ 3 · Trung/Hậu Kỳ 2)' : hxSizeSel.value + ' người (chọn tay)'));
